"""Turn a Kitty Code program into a main.py for a classroom micro:bit rover.

    python -m astrokitty.robot my-program.txt > main.py
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

from .kittycode import KittyCodeError, parse, to_tree

ROBOT = Path(__file__).resolve().parents[1] / "robot"


def build_main(source: str) -> str:
    program = to_tree(parse(source))
    vm = (ROBOT / "rover_vm.py").read_text(encoding="utf-8")
    driver = (ROBOT / "microbit_main.py").read_text(encoding="utf-8")
    return "\n".join([
        "# Generated by Astro Kitty. Flash this file to a BBC micro:bit V2 as main.py.",
        vm,
        driver,
        "PROGRAM = " + json.dumps(program),
        "main(PROGRAM)",
        "",
    ])


def main(argv: list[str] | None = None) -> int:
    argv = argv if argv is not None else sys.argv[1:]
    if len(argv) != 1:
        print(__doc__, file=sys.stderr)
        return 2
    try:
        sys.stdout.write(build_main(Path(argv[0]).read_text(encoding="utf-8")))
    except KittyCodeError as err:
        print(f"line {err.line}: {err.message}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
